ending'): ?><span class="fs-11 text-muted">Chờ người khác duyệt</span><?php else: ?><span class="fs-11 text-muted"><?= $entry['void_request_status']==='rejected'?'Yêu cầu bị từ chối':'Đã xử lý' ?></span><?php endif; ?><?php else: ?><span class="fs-11 text-muted">-</span><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$entries): ?><tr><td colspan="7" style="padding:28px;text-align:center;color:#667085">Ch&#432;a c&#243; giao d&#7883;ch trong s&#7893; qu&#7929;.</td></tr><?php endif; ?></tbody></table></div></div>
