<script>(function(){var form=document.getElementById('cashReceiptForm');if(!form)return;var phone=form.querySelector('[name=payer_phone]'),hint=document.getElementById('receiptPhoneHint'),description=document.getElementById('receiptDescription'),counter=document.getElementById('receiptWordCount');function words(){return description.value.trim()?description.value.trim().split(/\s+/).length:0}function count(){var total=words();counter.textContent=total+'/200 t\u1eeb';counter.style.color=total>200?'#b42318':'#667085'}function validPhone(){var value=phone.value.replace(/\D/g,'').slice(0,10);phone.value=value;var valid=/^0[35789]\d{8}$/.test(value);if(!valid){phone.setCustomValidity('S\u1ed1 \u0111i\u1ec7n tho\u1ea1i ph\u1ea3i c\u00f3 10 s\u1ed1 v\u00e0 b\u1eaft \u0111\u1ea7u b\u1eb1ng 03, 05, 07, 08 ho\u1eb7c 09.');hint.style.color='#b42318'}else{phone.setCustomValidity('');hint.style.color='#667085'}return valid}phone.addEventListener('input',validPhone);phone.addEventListener('blur',validPhone);description.addEventListener('input',count);form.addEventListener('submit',function(event){if(!validPhone()){event.preventDefault();phone.reportValidity();return}if(words()>200){event.preventDefault();alert('Di\u1ec5n gi\u1ea3i t\u1ed1i \u0111a 200 t\u1eeb.')}});count()})();</script>
<script>(function(){var form=document.getElementById('cashDisbursementForm');if(!form)return;var phone=form.querySelector('[name=payee_phone]'),hint=document.getElementById('disbursementPhoneHint'),description=document.getElementById('disbursementDescription'),counter=document.getElementById('disbursementWordCount');function words(){return description.value.trim()?description.value.trim().split(/\s+/).length:0}function count(){var total=words();counter.textContent=total+'/200 t\u1eeb';counter.style.color=total>200?'#b42318':'#667085'}function validPhone(){var value=phone.value.replace(/\D/g,'').slice(0,10);phone.value=value;var valid=/^0[35789]\d{8}$/.test(value);if(!valid){phone.setCustomValidity('S\u1ed1 \u0111i\u1ec7n tho\u1ea1i ph\u1ea3i c\u00f3 10 s\u1ed1 v\u00e0 b\u1eaft \u0111\u1ea7u b\u1eb1ng 03, 05, 07, 08 ho\u1eb7c 09.');hint.style.color='#b42318'}else{phone.setCustomValidity('');hint.style.color='#667085'}return valid}phone.addEventListener('input',validPhone);phone.addEventListener('blur',validPhone);description.addEventListener('input',count);form.addEventListener('submit',function(event){if(!validPhone()){event.preventDefault();phone.reportValidity();return}if(words()>200){event.preventDefault();alert('Di\u1ec5n gi\u1ea3i t\u1ed1i \u0111a 200 t\u1eeb.')}});count()})();</script>
